public IList<IList<string>> SolveNQueens(int n)
{
    var results = new List<IList<string>>();
    var placement = new int[n];               // placement[row] = column

    var columns = new HashSet<int>();
    var diagonalDown = new HashSet<int>();    // row + col is constant going down-right
    var diagonalUp = new HashSet<int>();      // row - col is constant going up-right

    Backtrack(0);
    return results;

    void Backtrack(int row)
    {
        if (row == n)
        {
            results.Add(BuildBoard(placement, n));
            return;
        }

        for (int col = 0; col < n; col++)
        {
            int down = row + col;
            int up = row - col;

            // Prune: this square is attacked
            if (columns.Contains(col) || diagonalDown.Contains(down) || diagonalUp.Contains(up))
            {
                continue;
            }

            placement[row] = col;
            columns.Add(col);
            diagonalDown.Add(down);
            diagonalUp.Add(up);

            Backtrack(row + 1);

            // Undo the choice before trying the next column
            columns.Remove(col);
            diagonalDown.Remove(down);
            diagonalUp.Remove(up);
        }
    }
}

private static IList<string> BuildBoard(int[] placement, int n)
{
    var board = new List<string>(n);

    foreach (int col in placement)
    {
        var row = new char[n];
        Array.Fill(row, '.');
        row[col] = 'Q';
        board.Add(new string(row));
    }

    return board;
}

public int TotalNQueens(int n)
{
    var columns = new HashSet<int>();
    var down = new HashSet<int>();
    var up = new HashSet<int>();
    return Count(0);

    int Count(int row)
    {
        if (row == n) return 1;

        int total = 0;

        for (int col = 0; col < n; col++)
        {
            int d = row + col, u = row - col;
            if (columns.Contains(col) || down.Contains(d) || up.Contains(u)) continue;

            columns.Add(col); down.Add(d); up.Add(u);
            total += Count(row + 1);
            columns.Remove(col); down.Remove(d); up.Remove(u);
        }

        return total;
    }
}
